      fr: ["Hauteur : 95 m au-dessus du niveau de la mer", "Longueur de la crête : env. 3 km", "Distance de Herning : 5 km", "Réserve naturelle Rind Banke : 150 ha", "Sentiers : 15 km balisés", "Végétation : principalement forêt de conifères et lande"],
