      en: ["Denmark's largest limestone quarry", "Geological outcrops", "Former coral reef", "Artificial relief"],
      es: ["La mayor cantera de caliza de Dinamarca", "Afloramientos geológicos", "Antiguo arrecife de coral", "Relieve artificial"],
      pt: ["A maior pedreira de calcário da Dinamarca", "Afloramentos geológicos", "Antigo recife de coral", "Relevo artificial"],
