      es: ["Zona montañosa boscosa", "Región de Roskilde", "Formas de suelo glaciales", "Área recreativa"],
      pt: ["Zona montanhosa arborizada", "Região de Roskilde", "Formas de solo glaciais", "Área de lazer"],
      fr: ["Collines boisées", "Région de Roskilde", "Formes de sol glaciaires", "Zone de loisirs"],
