    facts: {
      de: ["Moränenhügel", "Zentraljütland", "Sanfte Geländeform", "Eiszeitlicher Ursprung"],
      hu: ["Morénadomb", "Közép-Jütland", "Szelíd terepforma", "Jégkorszaki eredet"],
      ro: ["Deal morenic", "Centrul Iutlandei", "Formă de relief domoală", "Origine din epoca glaciară"],
      en: ["Moraine hill", "Central Jutland", "Gentle landform", "Ice age origin"],
      es: ["Colina de morrena", "Jutlandia Central", "Forma de relieve suave", "Origen de la Edad de Hielo"],
      pt: ["Colina de morena", "Jutlândia Central", "Forma de relevo suave", "Origem da era glacial"],
      fr: ["Colline morainique", "Jutland central", "Relief doux", "Origine glaciaire"],
    },
    imageHint: "Central Jutland landscape",
    descriptionAdvanced: {
      de: "Ål Bakke ist eine charakteristische Erhebung in der Region Salling im Norden Jütlands, die einen markanten Aussichtspunkt über den Limfjord bietet. Geologisch handelt es sich um eine Endmoräne, die während der Weichsel-Eiszeit durch den Druck der skandinavischen Eismassen aufgeschoben wurde. Die Landschaft ist geprägt durch steile Abhänge zum Fjord hin und eine wellige Hügelstruktur im Landesinneren. Die Vegetation wird durch offene Heideflächen und kleine Waldparzellen bestimmt, was dem Gebiet einen herben, nordischen Charakter verleiht. Historisch war die Anhöhe aufgrund ihrer weiten Sichtverhältnisse von strategischer Bedeutung für die Küstenüberwachung. Heute ist Ål Bakke ein beliebtes Ziel für Wanderer und Naturliebhaber, die die Ruhe und den weiten Panoramablick schätzen. Die Bodenbeschaffenheit aus sandigem Lehm und Kies ist typisch für die glazialen Ablagerungen der Region und beeinflusst die lokale Landwirtschaft.",
      hu: "Az Ål Bakke egy jellegzetes magaslat az észak-jütlandi Salling régióban, amely markáns kilátópontot kínál a Limfjordra. Geológiailag ez egy végmoréna, amelyet a Weichsel-jégkorszak idején a skandináv jégtömegek nyomása tolt fel. A tájat a fjord felé meredek lejtők, a szárazföld belseje felé pedig hullámzó dombszerkezet jellemzi. A növényzetet nyitott fenyérek és kis erdőfoltok határozzák meg, ami zord, északi karaktert kölcsönöz a területnek. Történelmileg a magaslat stratégiai jelentőséggel bírt a partmenti megfigyelés szempontjából a messzire nyúló kilátás miatt. Ma az Ål Bakke a túrázók és a természetkedvelők kedvelt célpontja, akik értékelik a nyugalmat és a széles panorámát. A homokos agyagból és kavicsból álló talajszerkezet tipikus a régió glaciális üledékeire, és befolyásolja a helyi mezőgazdaságot.",
      ro: "Ål Bakke este o înălțime caracteristică în regiunea Salling din nordul Iutlandei, oferind un punct de observație proeminent asupra Limfjord. Din punct de vedere geologic, este o morenă terminală împinsă de presiunea maselor de gheață scandinave în timpul glaciațiunii Weichsel. Peisajul este marcat de pante abrupte spre fjord și o structură colinară ondulată spre interiorul țării. Vegetația este dominată de lande deschise și mici parcele de pădure, oferind zonei un caracter nordic auster. Din punct de vedere istoric, înălțimea a avut o importanță strategică pentru supravegherea coastelor datorită vizibilității extinse. Astăzi, Ål Bakke este o destinație populară pentru drumeți și iubitorii de natură care apreciază liniștea și vederea panoramică vastă. Compoziția solului din argilă nisipoasă și pietriș este tipică pentru depozitele glaciare din regiune.",
      en: "Ål Bakke is a characteristic elevation in the Salling region of North Jutland, offering a prominent vantage point over the Limfjord. Geologically, it is a terminal moraine pushed up by the pressure of Scandinavian ice masses during the Weichselian ice age. The landscape is marked by steep slopes towards the fjord and an undulating hill structure further inland. The vegetation is dominated by open heathlands and small woodland plots, giving the area a rugged, Nordic character. Historically, the hill was of strategic importance for coastal surveillance due to its extensive views. Today, Ål Bakke is a popular destination for hikers and nature lovers who appreciate its tranquility and wide panoramic views. The soil composition of sandy clay and gravel is typical of the region's glacial deposits and influences local agriculture.",
      es: "Ål Bakke es una cresta morrénica arenosa en la costa oeste de Jutlandia, formada por la erosión del viento y el agua.",
      pt: "Ål Bakke é uma crista de morena arenosa na costa oeste da Jutlândia, formada pela erosão do vento e da água.",
      fr: "Ål Bakke est une crête morainique sableuse sur la côte ouest du Jutland, façonnée par l'érosion éolienne et hydraulique.",
    },
    factsAdvanced: {
      de: ["Bietet einen weiten Blick über das Gewässer des Limfjords.", "Gehört zur Hügellandschaft der Halbinsel Salling.", "Die Moräne entstand vor etwa 18.000 bis 20.000 Jahren.", "Besteht aus einer Mischung von Sand, Kies und Geschiebemergel.", "Die Umgebung ist für ihre reichen Fossilienfunde im Moler bekannt.", "Ein wichtiger Rastplatz für Zugvögel in der Limfjord-Region."],
      hu: ["Széles kilátást nyújt a Limfjord vízfelületére.", "A Salling-félsziget dombvidékéhez tartozik.", "A moréna körülbelül 18 000–20 000 évvel ezelőtt alakult ki.", "Homok, kavics és morénagyag keverékéből áll.", "A környék a moler-agyagban található gazdag kövületleleteiről ismert.", "Fontos pihenőhely a költöző madarak számára a Limfjord régióban."],
      ro: ["Oferă o vedere largă peste apele din Limfjord.", "Face parte din peisajul colinar al peninsulei Salling.", "Morena s-a format acum aproximativ 18.000 până la 20.000 de ani.", "Este compusă dintr-un amestec de nisip, pietriș și argilă morainică.", "Împrejurimile sunt cunoscute pentru descoperirile bogate de fosile în argila Moler.", "Un loc de popas important pentru păsările migratoare în regiunea Limfjord."],
      en: ["Offers a wide view across the waters of the Limfjord.", "Part of the hilly landscape of the Salling peninsula.", "The moraine was formed approximately 18,000 to 20,000 years ago.", "Composed of a mixture of sand, gravel, and glacial till.", "The surrounding area is known for rich fossil finds in Moler clay.", "An important resting place for migratory birds in the Limfjord region."],
      es: ["La cresta se eleva unos 35 metros sobre el nivel del mar.", "Se encuentra en el área de influencia de la costa arenosa del oeste de Jutlandia.", "Consiste en arenas de agua de deshielo de la Edad de Hielo.", "La superficie suele estar cubierta por dunas interiores.", "Se estabiliza mediante plantaciones de hierba de playa y pinos.", "Muestra fuertes huellas de erosión histórica por arena voladora."],
      pt: ["A crista eleva-se cerca de 35 metros acima do nível do mar.", "Localiza-se na área de influência da costa arenosa do oeste da Jutlândia.", "Consiste em areias de água de degelo da era glacial.", "A superfície é frequentemente coberta por dunas interiores.", "É estabilizada por plantações de erva-estendida e pinheiros.", "Mostra fortes vestígios de erosão histórica por areia voadora."],
      fr: ["La crête s'élève à environ 35 mètres au-dessus du niveau de la mer.", "Se situe dans la zone de captage de la côte ouest sableuse du Jutland.", "Composée de sables d'eaux de fonte glaciaires.", "La surface est souvent recouverte de dunes continentales.", "Stabilisée par des plantations d'oyats et de pins.", "Présente de fortes traces d'érosion historique par les sables volants."],
    },
